const item = $input.item;
const binaryKeys = Object.keys(item.binary || {});

if (binaryKeys.length === 0) {
  throw new Error('binary_missing: no binary audio file found in the incoming request. Expected a multipart/form-data field named "audio_file".');
}

let selectedKey;
if (binaryKeys.includes('audio_file')) {
  selectedKey = 'audio_file';
} else if (binaryKeys.includes('audio_file0')) {
  selectedKey = 'audio_file0';
} else {
  selectedKey = binaryKeys[0];
}

return {
  json: item.json,
  binary: {
    audio_file: item.binary[selectedKey]
  }
};

