const t = $json.transcription || {};
const utterances = Array.isArray(t.utterances) ? t.utterances : [];
const durationMs = (typeof t.duration_ms === 'number' && t.duration_ms > 0) ? t.duration_ms : null;
const fullText = t.full_text || '';
const webhookBody = $('Webhook Trigger').item.json.body || {};

let speakerToRole = {};
let taggedLines = [];
let agentWords = 0;
let customerWords = 0;
let totalSpeechMs = 0;
let assumptionNotes = [];

if (utterances.length > 0) {
  for (const u of utterances) {
    const spk = u.speaker || 'Unknown';
    if (!(spk in speakerToRole)) {
      speakerToRole[spk] = Object.keys(speakerToRole).length === 0 ? 'Agent' : 'Customer';
    }
    const role = speakerToRole[spk];
    const text = (u.text || '').trim();
    if (!text) continue;
    taggedLines.push(role + ': ' + text);
    const wc = text.split(/\s+/).filter(Boolean).length;
    if (role === 'Agent') { agentWords += wc; } else { customerWords += wc; }
    if (typeof u.start_ms === 'number' && typeof u.end_ms === 'number' && u.end_ms > u.start_ms) {
      totalSpeechMs += (u.end_ms - u.start_ms);
    }
  }
  assumptionNotes.push('speaker_role_mapping_heuristic: first speaker to talk assumed Agent, all other distinct speakers folded into Customer (AssemblyAI diarization returns generic Speaker labels, not named roles).');
} else {
  taggedLines.push('Agent: ' + fullText);
  assumptionNotes.push('no_diarization_utterances: AssemblyAI returned no utterances; the entire transcript was tagged as Agent only, Customer turns are unknown.');
}

const taggedTranscript = taggedLines.join('\n');
const totalWords = agentWords + customerWords;
const agentTalkRatioRaw = totalWords > 0 ? (agentWords / totalWords) : null;

let callDurationSecondsRaw;
let durationIsEstimate = false;
if (durationMs !== null) {
  callDurationSecondsRaw = Math.round(durationMs / 1000);
} else {
  callDurationSecondsRaw = Math.round((totalWords / 130) * 60);
  durationIsEstimate = true;
  assumptionNotes.push('call_duration_estimated: no measured audio duration from AssemblyAI; estimated from word count at ~130 wpm, not measured.');
}

const speechToNonSpeechRatioRaw = (durationMs && totalSpeechMs > 0) ? (totalSpeechMs / durationMs) : null;
const silenceRatioRaw = (speechToNonSpeechRatioRaw !== null) ? (1 - speechToNonSpeechRatioRaw) : null;
const speakingRateWpmRaw = (callDurationSecondsRaw > 0) ? Math.round(totalWords / (callDurationSecondsRaw / 60)) : null;

function clampVal(v, lo, hi, fallback) {
  if (v === null || v === undefined || isNaN(v)) return { value: fallback, clamped: true, reason: 'missing_measurement_used_dataset_midpoint_fallback' };
  if (v < lo) return { value: lo, clamped: true, reason: 'measured_value_below_service_accepted_range' };
  if (v > hi) return { value: hi, clamped: true, reason: 'measured_value_above_service_accepted_range' };
  return { value: v, clamped: false, reason: null };
}

const durationClamp = clampVal(callDurationSecondsRaw, 180, 900, 420);
const silenceClamp = clampVal(silenceRatioRaw, 0.05, 0.35, 0.18);
const wpmClamp = clampVal(speakingRateWpmRaw, 100, 190, 145);
const speechRatioClamp = clampVal(speechToNonSpeechRatioRaw, 0.65, 0.95, 0.82);
const talkRatioClamp = clampVal(agentTalkRatioRaw, 0.35, 0.75, 0.55);

const priceKeywords = /\b(price|pricing|cost|budget|discount|quote)\b/gi;
const competitorKeywords = /\b(competitor|competitors|alternative|other vendor|other provider)\b/gi;
const priceMentionsCount = (taggedTranscript.match(priceKeywords) || []).length;
const competitorMentionsCount = (taggedTranscript.match(competitorKeywords) || []).length;
const questionCount = (taggedTranscript.match(/\?/g) || []).length;

const clampedFieldsList = [
  { field: 'call_duration_seconds', c: durationClamp },
  { field: 'silence_ratio', c: silenceClamp },
  { field: 'speaking_rate_wpm', c: wpmClamp },
  { field: 'speech_to_non_speech_ratio', c: speechRatioClamp },
  { field: 'agent_talk_ratio', c: talkRatioClamp },
].filter(x => x.c.clamped).map(x => ({ field: x.field, reason: x.c.reason }));

return [{
  json: {
    transcription: t,
    submission_metadata: {
      agent_name: webhookBody.agent_name || null,
      call_date: webhookBody.call_date || null,
      customer_name: webhookBody.customer_name || null,
      notes: webhookBody.notes || null,
    },
    tagged_transcript: taggedTranscript,
    transcript_features: {
      word_count: totalWords,
      agent_word_count: agentWords,
      customer_word_count: customerWords,
      question_count: questionCount,
      price_mentions_count: priceMentionsCount,
      competitor_mentions_count: competitorMentionsCount,
    },
    audio_features_measured: {
      call_duration_seconds: callDurationSecondsRaw,
      call_duration_is_estimate: durationIsEstimate,
      silence_ratio: silenceRatioRaw,
      speech_to_non_speech_ratio: speechToNonSpeechRatioRaw,
      speaking_rate_wpm: speakingRateWpmRaw,
      agent_talk_ratio: agentTalkRatioRaw,
    },
    audio_features_for_signal_service: {
      call_duration_seconds: durationClamp.value,
      silence_ratio: silenceClamp.value,
      speaking_rate_wpm: wpmClamp.value,
      speech_to_non_speech_ratio: speechRatioClamp.value,
      agent_talk_ratio: talkRatioClamp.value,
    },
    clamped_fields: clampedFieldsList,
    pipeline_assumptions: assumptionNotes,
  }
}];

const transcript = $json.tagged_transcript || '';
const lengthOk = transcript.length >= 20;
const injectionPatterns = [/ignore (all|any|previous|the above) instructions/i, /system prompt/i, /jailbreak/i, /disregard (all|the above)/i, /you are now/i, /act as (an? )?(unrestricted|unfiltered)/i];
const promptInjectionDetected = injectionPatterns.some(r => r.test(transcript));
const offensivePatterns = [/\bfuck\b/i, /\bshit\b/i, /\basshole\b/i, /\bidiot\b/i];
const offensiveDetected = offensivePatterns.some(r => r.test(transcript));
const salesKeywords = /\b(price|pricing|cost|contract|deal|purchase|subscription|demo|proposal|crm|quote|discount|renewal|budget|sales|product|solution|onboarding|trial)\b/i;
const possibleOffTopic = !salesKeywords.test(transcript);

const reasons = [];
if (!lengthOk) reasons.push('transcript_too_short');
if (promptInjectionDetected) reasons.push('prompt_injection_detected');
if (offensiveDetected) reasons.push('offensive_content_detected');
if (possibleOffTopic) reasons.push('possible_off_topic');

const pass = lengthOk && !promptInjectionDetected && !offensiveDetected && !possibleOffTopic;

return [{
  json: {
    ...$json,
    post_transcription_check: {
      pass,
      reasons,
      note: 'Inline deterministic n8n check (Code node) -- not a call to guardrails_service, which does not implement a post_transcription stage yet.'
    }
  }
}];

function extractText(item) {
  const candidates = [item.text, item.content, item.output, item.response, item.message, item && item.candidates && item.candidates[0] && item.candidates[0].content && item.candidates[0].content.parts && item.candidates[0].content.parts[0] && item.candidates[0].content.parts[0].text];
  for (const c of candidates) { if (typeof c === 'string' && c.trim().length > 0) return c; }
  return null;
}
function parseJsonLoose(text) {
