  const cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(cleaned); } catch (e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) { try { return JSON.parse(match[0]); } catch (e2) { return null; } }
    return null;
  }
}
const raw = extractText($json);
let parsed = parseJsonLoose(raw);
const VALID_INTENT = ['high','medium','low','unclear'];
const VALID_OBJECTION = ['price','timing','trust','competitor','no_need','authority','integration','security','other','none'];
const VALID_SENTIMENT = ['positive','neutral','negative','mixed'];
