return [{ json: { rag_payload: ragPayload, signal_payload: signalPayload, relevant_services: enrichment.relevant_services } }];

const merged = $json;
const extraction = ($('Parse Gemini Extraction').item.json.extraction) || {};
const transcriptNode = $('Build Speaker-Tagged Transcript').item.json;

return [{
