  }
}
const raw = extractText($json);
let parsed = parseJsonLoose(raw);
let parse_error = null;
if (!parsed || typeof parsed !== 'object') { parse_error = 'final_analysis_response_not_valid_json'; parsed = {}; }

const ctx = $('Assemble Final Analysis Context').item.json;

const knownGaps = [];
knownGaps.push('Post-transcription content guardrails were enforced by an inline n8n deterministic check, not the guardrails_service (its POST /check/input does not yet implement a post_transcription stage).');
knownGaps.push('Output guardrails (POST /check/output) are not implemented by guardrails_service yet; this result has not been independently checked for invented facts or missing citations by that service.');
if (ctx.clamped_fields && ctx.clamped_fields.length > 0) {
  knownGaps.push('Audio-derived features (' + ctx.clamped_fields.map(c => c.field).join(', ') + ') were clamped to the Call Signal Analyser mock service accepted numeric ranges and may not reflect this call true measured values.');
}
if (ctx.pipeline_assumptions && ctx.pipeline_assumptions.length > 0) {
  ctx.pipeline_assumptions.forEach(a => knownGaps.push(a));
}
if (parse_error) {
  knownGaps.push('The Final Analysis Chain response could not be parsed as JSON; default/fallback values were substituted for missing fields.');
}

const geminiLimitations = (typeof parsed.limitations === 'string' && parsed.limitations.trim()) ? parsed.limitations.trim() : '';
const finalLimitations = [geminiLimitations].concat(knownGaps).filter(Boolean).join(' ');

const finalAnalysis = {
  transcript: typeof parsed.transcript === 'string' ? parsed.transcript : ctx.tagged_transcript,
